def markedMean (h delta a b : ℝ) (theta arm : Bool) (sigma : SignArray d h delta) (x : Cov d) : ℝ :=
  1/2 + b*signField h delta sigma true x + thetaSign arm * markedContrast h a b theta x / 2 -- @realizes b(control amplitude)

/-- Given [the specified input d](hyp:d), [the specified input h](hyp:h), [loc cube](goal) is the corresponding construction. -/
def locCube (d : ℕ) (h : ℝ) : Set (Cov d) :=
  {x | ∀ i, x i ∈ Icc (1/2-h/2) (1/2+h/2)} -- @realizes Ch(local cube) @realizes h(localization input)

/-- Given [the specified input d](hyp:d), [the specified input h](hyp:h), [loc cube](goal) is the corresponding construction. -/
def locCube (d : ℕ) (h : ℝ) : Set (Cov d) :=
  {x | ∀ i, x i ∈ Icc (1/2-h/2) (1/2+h/2)} -- @realizes Ch(local cube) @realizes h(localization input)

/-- Given [the specified input d](hyp:d), [the specified input h](hyp:h), [loc law](goal) is the corresponding construction. -/
def locLaw (d : ℕ) (h : ℝ) : Measure (Cov d) :=
  ENNReal.ofReal (h^(-(d:ℝ))) • volume.restrict (locCube d h) -- @realizes nuh(known localization law)

/-- Given [the specified input h](hyp:h), [the specified input x](hyp:x), [coarse basis](goal) is the corresponding construction. -/
def coarseBasis (h : ℝ) (x : Cov d) (κ : PolyIdx d) : ℝ :=
  ∏ i, legendre (κ.1 i) ((x i-1/2)/h) -- @realizes r(scaled Legendre vector)

/-- Given [the specified input h](hyp:h), [the specified input J](hyp:J), [the specified input x](hyp:x), [the specified input z](hyp:z), [fine basis](goal) is the corresponding construction. -/
def fineBasis (h : ℝ) (J : ℕ) (x : Cov d) (zκ : FineIdx d J) : ℝ :=
  if x ∈ cell h J zκ.1 then Real.sqrt ((J:ℝ)^d) *
    ∏ i, legendre (zκ.2.1 i) ((x i-(1/2-h/2+((zκ.1 i:ℝ)+1/2)*(h/J)))/(h/J))
  else 0 -- @realizes bvec(cellwise Legendre basis)

/-- Given [the specified input d](hyp:d), [the specified input h](hyp:h), [the specified input J](hyp:J), [the specified input x](hyp:x), [the specified input xp](hyp:xp), [fine kernel](goal) is the corresponding construction. -/
def fineKernel (d : ℕ) (h : ℝ) (J : ℕ) (x xp : Cov d) : ℝ :=
  ∑ z : FineIdx d J, fineBasis h J x z * fineBasis h J xp z -- @realizes K(projection kernel)

/-- Given [the specified input d](hyp:d), [the specified input h](hyp:h), [the specified input J](hyp:J), [the specified input f](hyp:f), [the specified input x](hyp:x), [proj op](goal) is the corresponding construction. -/
def projOp (d : ℕ) (h : ℝ) (J : ℕ) (f : Cov d → ℝ) (x : Cov d) : ℝ :=
  ∫ xp, fineKernel d h J x xp * f xp ∂locLaw d h -- @realizes Proj(kernel integral)

aux_classRisk.statement:
/-- Given [the specified input d](hyp:d), [the specified input alpha](hyp:alpha), [the specified input beta](hyp:beta), [the specified input gamma](hyp:gamma), [the specified input L](hyp:L), [the overlap level eps](hyp:eps), [the specified input n](hyp:n), [the specified input m](hyp:m), [the specified input T](hyp:T), [the specified input P](hyp:P), [class risk](goal) is the corresponding construction. -/
def classRisk (d : ℕ) (alpha beta gamma L eps : ℝ) (n m : ℕ) (T : Decision d n m)
    (P : {P : PrimitiveLaw d // PrimitiveClass alpha beta gamma L eps P}) : ℝ≥0∞ := risk T P.1 P.2

aux_recordAdj.statement:
/-- Given [the specified input h](hyp:h), [the specified input delta](hyp:delta), [the specified input x](hyp:x), [the specified input i](hyp:i), [the specified input j](hyp:j), [record adj](goal) is the corresponding construction. -/
def recordAdj (h delta : ℝ) (x : Fin (n+m) → Cov d) (i j : Fin (n+m)) : Prop :=
  i ≠ j ∧ x i ∈ locCube d h ∧ x j ∈ locCube d h ∧ maxDist (x i) (x j) ≤ 2*delta

aux_signPrior.statement:
/-- Given [the specified input H](hyp:H), [the specified input theta](hyp:theta), [sign prior](goal) is the corresponding construction. -/
def signPrior (H : MarkedPriors d) (theta : Bool) : Measure (PriorSign H) :=
  ∑ sigma, ENNReal.ofReal (H.weight theta sigma) • Measure.dirac sigma

aux_singletonMixture.statement:
/-- Given [the specified input H](hyp:H), [the specified input theta](hyp:theta), [the specified input x](hyp:x), [singleton mixture](goal) is the corresponding construction. -/
def singletonMixture (H : MarkedPriors d) (theta : Bool) (x : Cov d) : Measure (Bool × Bool) :=
  ∑ sigma, ENNReal.ofReal (H.weight theta sigma) • conditionalObserved (H.law theta sigma) x

aux_upperRate.statement:
/-- Given [the specified input d](hyp:d), [the specified input alpha](hyp:alpha), [the specified input beta](hyp:beta), [the specified input gamma](hyp:gamma), [the specified input n](hyp:n), [the specified input m](hyp:m), [upper rate](goal) is the corresponding construction. -/
def upperRate (d : ℕ) (alpha beta gamma : ℝ) (n m : ℕ) : ℝ :=
  max (oracleRate d gamma n) (((n:ℝ)*((n:ℝ)+m))^(-(gamma/bigDelta d alpha beta gamma))) -- @realizes rup(upper rate)

isClosed_lambdaMin_ge.statement:
/-- The guard is the intersection of closed inequalities over all unit vectors.  Given [the specified input d](hyp:d), [the specified input a](hyp:a), [the is closed lambda min ge conclusion](goal) holds. -/
lemma isClosed_lambdaMin_ge (d : ℕ) (a : ℝ) :
    IsClosed {Q : PolyIdx d → PolyIdx d → ℝ | a ≤ lambdaMin Q}

weightedTreatmentFeature.statement:
/-- Localization weights a covariate feature and its treatment bit.  Given [the specified input d](hyp:d), [the specified input h](hyp:h), [the specified input f](hyp:f), [the specified input z](hyp:z), [weighted treatment feature](goal) is the corresponding construction. -/
def weightedTreatmentFeature {d : ℕ} (h : ℝ) (f : Cov d → ℝ)
    (z : Cov d × Bool) : ℝ := locWeight h z.1 * f z.1 * bit z.2

datasetCovariates.statement:
/-- Concatenate the covariates of the original labeled and auxiliary records.  Given [the specified input d](hyp:d), [the specified input n](hyp:n), [the specified input m](hyp:m), [the specified input D](hyp:D), [dataset covariates](goal) is the corresponding construction. -/
def datasetCovariates {d n m : ℕ} (D : Dataset d n m) : Fin (n+m) → Cov d :=
  recordCovariates (fun i => (D.1 i).1) (fun j => (D.2 j).1)

datasetSpins.statement:
/-- Retain the two observed bits in labeled records and the treatment bit in auxiliaries.  Given [the specified input d](hyp:d), [the specified input n](hyp:n), [the specified input m](hyp:m), [the specified input D](hyp:D), [dataset spins](goal) is the corresponding construction. -/
def datasetSpins {d n m : ℕ} (D : Dataset d n m) : RecordSpins n m :=
  (fun i => (D.1 i).2, fun j => (D.2 j).2)

datasetDensity.statement:
/-- The original-record mixture likelihood is the conditional mixed likelihood.  Given [the specified input d](hyp:d), [the specified input n](hyp:n), [the specified input m](hyp:m), [the specified input H](hyp:H), [the specified input theta](hyp:theta), [the specified input D](hyp:D), [dataset density](goal) is the corresponding construction. -/
def datasetDensity {d n m : ℕ} (H : MarkedPriors d) (theta : Bool)
    (D : Dataset d n m) : ℝ := mixedDensity H theta (datasetCovariates D) (datasetSpins D)

legendreAffineCoeff.statement:
/-- Triangular coefficients for a one-dimensional affine Legendre change.  Given [the specified input k](hyp:k), [the specified input j](hyp:j), [the specified input a](hyp:a), [the specified input b](hyp:b), [legendre affine coeff](goal) is the corresponding construction. -/
def legendreAffineCoeff (k j : ℕ) (a b : ℝ) : ℝ :=
  if k = 0 then (if j = 0 then 1 else 0)
  else if k = 1 then (if j = 0 then Real.sqrt 12*a else if j = 1 then b else 0)
  else (if j = 0 then Real.sqrt 5*(6*a^2+b^2/2-1/2)
    else if j = 1 then Real.sqrt 5*Real.sqrt 12*a*b else if j = 2 then b^2 else 0)

rectangular_primitive_uniform_design.statement:
/-- Primitive-class membership fixes the actual covariate marginal, regardless of raw versions.  Given [the specified input d](hyp:d), [the specified input alpha](hyp:alpha), [the specified input beta](hyp:beta), [the specified input gamma](hyp:gamma), [the specified input L](hyp:L), [the overlap level eps](hyp:eps), [the specified input P](hyp:P), [the specified input hP](hyp:hP), [the rectangular primitive uniform design conclusion](goal) holds. -/
lemma rectangular_primitive_uniform_design {d : ℕ} {alpha beta gamma L eps : ℝ}
    (P : PrimitiveLaw d) (hP : PrimitiveClass alpha beta gamma L eps P) : UniformDesign P

rectangularTreatmentEnumeration.statement:
/-- An enumeration of the treatment role by its prescribed count.  Given [the specified input n](hyp:n), [the specified input m](hyp:m), [rectangular treatment enumeration](goal) is the corresponding construction. -/
def rectangularTreatmentEnumeration (n m : ℕ) : Fin (treatmentCount n m) ≃ (roleSplit n m).2 :=
  (Fintype.equivFinOfCardEq (by simpa using (population_role_cardinalities n m).2)).symm

rectangularOutcomeEnumeration.statement:
/-- An enumeration of the outcome role by its prescribed count.  Given [the specified input n](hyp:n), [the specified input m](hyp:m), [rectangular outcome enumeration](goal) is the corresponding construction. -/
def rectangularOutcomeEnumeration (n m : ℕ) : Fin (outcomeCount n) ≃ (roleSplit n m).1 :=
  (Fintype.equivFinOfCardEq (by simpa using (population_role_cardinalities n m).1)).symm

rectangularOutcomeAverage.statement:
/-- A first-order average over the labeled outcome role.  Given [the specified input d](hyp:d), [the specified input n](hyp:n), [the specified input m](hyp:m), [the specified input f](hyp:f), [the specified input w](hyp:w), [rectangular outcome average](goal) is the corresponding construction. -/
def rectangularOutcomeAverage {d n m : ℕ} (f : Cov d × Bool × Bool → ℝ) (w : Sample d n m) : ℝ :=
  (outcomeCount n:ℝ)⁻¹ * ∑ j ∈ (roleSplit n m).1, f (w.1.1 j)
